   260                        int indent, const uint8_t *prev_val) {
   261      const void *val = nullptr;
   262      if (fixed) {
   263        // The only non-scalar fields in structs are structs or arrays.
   264        FLATBUFFERS_ASSERT(IsStruct(fd.value.type) || IsArray(fd.value.type));
